    fn authored_topology_state(writer:&WideOwnerWriter)->serde_json::Value{
        let mut nodes=Vec::new();let mut ids:Vec<_>=writer.kernel.nodes.iter().map(|v|*v.key()).collect();ids.sort_unstable();for id in ids{let node=writer.kernel.nodes.get(&id).unwrap();let centroid=writer.kernel.node_centroid(id,node.centroid());let record=writer.kernel.live_topology.as_ref().unwrap().get(writer.kernel.node_owner(id,matches!(node.value(),TreeNode::Leaf(_))),id).unwrap();let kind=match node.value(){TreeNode::Leaf(v)=>{let leaf=writer.backend().snapshot(id).unwrap();let live=leaf.ids.iter().zip(&leaf.versions).filter(|(id,v)|writer.backend().current(**id)==Some(**v)).count();serde_json::json!({"leaf_physical":v.length,"live":live,"ids":leaf.ids,"versions":leaf.versions,"codes":leaf.codes,"pending":v.parent_id.is_some() && v.length>0 && v.length<writer.kernel.config.merge_threshold})},TreeNode::Internal(v)=>serde_json::json!({"children":v.children})};nodes.push(serde_json::json!({"id":id,"parent":match node.value(){TreeNode::Leaf(v)=>v.parent_id,TreeNode::Internal(v)=>v.parent_id},"kind":kind,"centroid_bits":centroid.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"live_record_present":record.is_some(),"live_centroid_matches":record.as_ref().is_some_and(|r|bits_centroid(&r.centroid)==bits_centroid(&centroid))}));}serde_json::json!({"root":writer.kernel.root_id(),"nodes":nodes,"pending":writer.kernel.pending_balance_leaves(),"shape":writer.kernel.construction_shape()})
    }
    fn bits_centroid(v:&[f32])->Vec<u32>{v.iter().map(|v|v.to_bits()).collect()}
    #[tokio::test(flavor="multi_thread",worker_threads=2)]
    async fn authored_parallel_unary_contraction_scalar_and_batch_authority(){
        let input=rows();let mut outcomes=Vec::new();let mut initial=Vec::new();
        for scalar in [true,false]{let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let mut c=config();c.split_threshold=256;c.merge_threshold=97;let mut writer=WideOwnerWriter::new(32,DistanceFunction::Euclidean,c,2,&[0,1,2],40,p.clone(),super::super::super::owner_vector_store::VectorLimits::default()).unwrap();writer.enable_topology(p.clone(),super::super::super::super::live_topology::Limits{entries:2,cache_payload_bytes:512,record_payload_bytes:512,wave_rows:2,mutation_working_bytes:1024*1024}).unwrap();writer.add_phase(&input,1).unwrap();
            {let _tree=writer.kernel.tree_lock.lock();let _work=writer.kernel.topology_working(8);let _scope=writer.kernel.topology_mutation();writer.kernel.take_reference_node(0).unwrap();writer.kernel.tombstones.insert(0);writer.kernel.dirty_nodes.remove(&0);let mut centers=Vec::new();for(group,chunk) in input.chunks(48).enumerate(){let id=group as u32+1;let parent=id+2;let mut center=vec![0.;32];for(_,v) in chunk{for(d,value) in v.iter().enumerate(){center[d]+=*value/48.;}}let codes:Vec<_>=chunk.iter().flat_map(|(_,v)|Code::<1>::quantize(v,&center).as_ref().to_vec()).collect();writer.kernel.install_reference_node(id,TreeNode::Leaf(LeafNode{centroid:center.clone(),centroid_code:writer.kernel.quantize_origin(&center),ids:chunk.iter().map(|v|v.0).collect(),versions:vec![1;48],codes,parent_id:Some(parent),length:48}));writer.kernel.mark_node_dirty(id);writer.kernel.install_reference_node(parent,TreeNode::Internal(InternalNode{centroid:center.clone(),centroid_code:writer.kernel.quantize_origin(&center),children:vec![id],parent_id:Some(5)}));writer.kernel.mark_node_dirty(parent);centers.push(center);}let center:Vec<_>=centers[0].iter().zip(&centers[1]).map(|(a,b)|(a+b)/2.).collect();writer.kernel.install_reference_node(5,TreeNode::Internal(InternalNode{centroid:center.clone(),centroid_code:writer.kernel.quantize_origin(&center),children:vec![3,4],parent_id:None}));writer.kernel.mark_node_dirty(5);writer.kernel.root_id.store(5,Ordering::Relaxed);writer.kernel.next_node_id.store(6,Ordering::Relaxed);}
            assert_eq!(writer.move_leaf(2,1).unwrap(),48);writer.backend().scalar_scrub_locations.store(scalar,Ordering::Relaxed);let pre=authored_topology_state(&writer);let snapshot=writer.save(&p).await.unwrap();let mut old=Reader64::open(&p,snapshot,256).await.unwrap();let census=old.census().await.unwrap();assert_eq!(census.len(),96);initial.push(pre.clone());writer.balance_phase(4).unwrap();let post=authored_topology_state(&writer);let saved=writer.save(&p).await.unwrap();let mut current=Reader64::open(&p,saved,256).await.unwrap();assert_eq!(current.census().await.unwrap().len(),96);assert_eq!(old.census().await.unwrap(),census);let merges=writer.kernel.stats.merges.load(Ordering::Relaxed);assert!(merges>0);println!("AUTHORED_UNARY {}",serde_json::json!({"scalar_locations":scalar,"before":pre,"after":post,"merges":merges,"locations":writer.backend().authority.location_observation(),"old_reader_unchanged":true,"current_census":96}));outcomes.push(writer.kernel.construction_shape()["depth"].as_u64().unwrap());}
        assert_eq!(initial[0],initial[1],"identical authored pre-contraction state");assert_eq!(outcomes,vec![0,0],"both authority modes must fully contract the authored unary root chain");
    }
